/* Signature Welsh Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Rhysgwen": "From Rhys + gwen (blessed).", "Gwencarys": "From gwen + Carys (love): 'blessed love'.", "Dylanmor": "From Dylan + mor (sea): 'sea wave'.", "Caryswen": "From Carys + gwen.", "Owainafon": "From Owain + afon (river).", "Branwenlo": "From Branwen + ?? built on bran (raven).", "Aprhysgwen": "Signature surname in ap style: 'son of Rhysgwen'.", "Abowainafon": "Signature surname in ab style.", "Jonesgwen": "Signature surname blending Jones + gwen.", "Pryceylan": "Signature surname blending Price + Dylan."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Rhysgwen';
console.log(lookup(q));

